gHe(){return"\u041e\u0431\u043b\u0456\u043a\u043e\u0432\u0438\u0439 \u0437\u0430\u043f\u0438\u0441 \u043d\u0435 \u043c\u043e\u0436\u043d\u0430 \u0432\u0438\u0434\u0430\u043b\u0438\u0442\u0438, \u0434\u043e\u043a\u0438 \u0454 \u0430\u043a\u0442\u0438\u0432\u043d\u0435 \u0437\u043e\u0431\u043e\u0432\u2019\u044f\u0437\u0430\u043d\u043d\u044f. \u0423\u0440\u0435\u0433\u0443\u043b\u044e\u0439\u0442\u0435 \u0439\u043e\u0433\u043e \u0442\u0430 \u043f\u043e\u0432\u0442\u043e\u0440\u0456\u0442\u044c \u0441\u043f\u0440\u043e\u0431\u0443."},
