gHC(){return"\u041e\u0431\u043b\u0456\u043a\u043e\u0432\u0438\u0439 \u0437\u0430\u043f\u0438\u0441 \u0456\u0437 \u0446\u0456\u0454\u044e \u0430\u0434\u0440\u0435\u0441\u043e\u044e \u0435\u043b\u0435\u043a\u0442\u0440\u043e\u043d\u043d\u043e\u0457 \u043f\u043e\u0448\u0442\u0438 \u0432\u0436\u0435 \u0456\u0441\u043d\u0443\u0454. \u0423\u0432\u0456\u0439\u0434\u0456\u0442\u044c \u0430\u0431\u043e \u0432\u043a\u0430\u0436\u0456\u0442\u044c \u0456\u043d\u0448\u0443 \u0430\u0434\u0440\u0435\u0441\u0443."},
