gVM(){return"\u0423\u043a\u0430\u0436\u0456\u0442\u044c \u043f\u0440\u043e\u0444\u0456\u043b\u044c\u043d\u0443 \u043f\u0440\u043e\u0444\u0435\u0441\u0456\u0439\u043d\u0443 \u0430\u0431\u043e \u0432\u0438\u0449\u0443 \u043e\u0441\u0432\u0456\u0442\u0443: \u0437\u0430\u043a\u043b\u0430\u0434, \u043f\u0440\u043e\u0433\u0440\u0430\u043c\u0443 \u0447\u0438 \u0441\u043f\u0435\u0446\u0456\u0430\u043b\u044c\u043d\u0456\u0441\u0442\u044c, \u043a\u0432\u0430\u043b\u0456\u0444\u0456\u043a\u0430\u0446\u0456\u044e \u0442\u0430 \u0440\u0456\u043a \u0437\u0430\u043a\u0456\u043d\u0447\u0435\u043d\u043d\u044f. \u0414\u0438\u043f\u043b\u043e\u043c\u0438 \u043c\u043e\u0436\u043d\u0430 \u0434\u043e\u0434\u0430\u0442\u0438 \u043d\u0438\u0436\u0447\u0435."},
gVI(){return"\u041f\u0435\u0440\u0435\u043b\u0456\u0447\u0456\u0442\u044c \u043a\u0443\u0440\u0441\u0438, \u0441\u0435\u043c\u0456\u043d\u0430\u0440\u0438 \u0439 \u043f\u0456\u0434\u0432\u0438\u0449\u0435\u043d\u043d\u044f \u043a\u0432\u0430\u043b\u0456\u0444\u0456\u043a\u0430\u0446\u0456\u0457, \u043f\u043e\u0432\u2019\u044f\u0437\u0430\u043d\u0456 \u0437 \u0432\u0430\u0448\u0438\u043c\u0438 \u043f\u043e\u0441\u043b\u0443\u0433\u0430\u043c\u0438. \u0423\u043a\u0430\u0436\u0456\u0442\u044c \u043e\u0440\u0433\u0430\u043d\u0456\u0437\u0430\u0442\u043e\u0440\u0430, \u0442\u0435\u043c\u0443, \u0440\u0456\u043a \u0456 \u0437\u0434\u043e\u0431\u0443\u0442\u0456 \u043d\u0430\u0432\u0438\u0447\u043a\u0438."},
